import * as Effect from "effect/Effect"
import * as Data from "effect/Data"
import { foreign, nativeTheme } from "./foreign.js"

/** The session the host reports, read when the program is built. */
export const program = () => Effect.succeed(foreign())

export const watch = (listener: () => void) => {
  nativeTheme.on("updated", listener)
  return Effect.void
}

export class Mapped extends Data.TaggedError("Mapped")<{ readonly message: string }> {}

export function mapper() {
  return (cause: unknown) => new Mapped({ message: foreign() + String(cause) })
}

export async function later() {
  return foreign()
}

export const label = "session"
